// CustomMaxHeapImplementation
class CustomMaxHeapImplementation {int[]a=new int[16];int n=0;public void add(int x){if(n==a.length)a=java.util.Arrays.copyOf(a,a.length*2);int i=n++;a[i]=x;while(i>0){int p=(i-1)/2;if(a[p]>=a[i])break;swap(p,i);i=p;}}public int remove(){if(n==0)throw new IllegalStateException();int v=a[0];a[0]=a[--n];int i=0;while(true){int l=2*i+1,r=l+1,b=i;if(l<n&&a[l]>a[b])b=l;if(r<n&&a[r]>a[b])b=r;if(b==i)break;swap(i,b);i=b;}return v;}private void swap(int i,int j){int t=a[i];a[i]=a[j];a[j]=t;}public int peek(){if(n==0)throw new IllegalStateException();return a[0];}public int size(){return n;}}
